    python3 - "$CATALOG_URL" <<'PYCATALOG' &
import sys, json
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse

port = int(sys.argv[1].rsplit(":", 1)[-1])

# product_id -> flags + price
PRODUCTS = {
    "prod-10":      {"store": "test-store-001", "virtual": False, "shippable": True,  "free": False, "price": 13.00},
    "prod-virtual": {"store": "test-store-001", "virtual": True,  "shippable": False, "free": False, "price": 9.00},
    "prod-store2":  {"store": "other-store-999","virtual": False, "shippable": True,  "free": False, "price": 20.00},
    "prod-free":    {"store": "test-store-001", "virtual": False, "shippable": True,  "free": True,  "price": 0.00},
}
# attribute ownership: attribute_id -> product_id
ATTRS = {"attr-5": "prod-10"}

def parse_pid(path):
    # /api/v1/catalog/products/{id}[/final-price|/attributes]
    parts = [p for p in path.split("/") if p]
    try:
        i = parts.index("products")
        return parts[i + 1]
    except (ValueError, IndexError):
        return None

class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _send(self, code, body):
        payload = json.dumps(body).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def _price(self, pid):
        p = PRODUCTS.get(pid)
        fp = p["price"]
        return {"final_price": fp, "original_price": fp, "discounted_price": fp,
                "default_price": True, "discounted": False, "discount_percent": 0}

    def do_GET(self):
        path = urlparse(self.path).path
        pid = parse_pid(path)
        if pid is None or pid not in PRODUCTS:
            return self._send(404, {"error": "not_found", "message": "product not found"})
        p = PRODUCTS[pid]
        if path.endswith("/final-price"):
            return self._send(200, self._price(pid))
        if path.endswith("/attributes"):
            items = [{"id": a} for a, owner in ATTRS.items() if owner == pid]
            return self._send(200, {"items": items})
        # base product
        return self._send(200, {"id": pid, "sku": "SKU-" + pid, "available": True,
                                "visible": True, "virtual": p["virtual"],
                                "shippable": p["shippable"], "free": p["free"],
                                "store_id": p["store"]})

    def do_POST(self):
        path = urlparse(self.path).path
        pid = parse_pid(path)
        length = int(self.headers.get("Content-Length", 0) or 0)
        if length:
            self.rfile.read(length)
        if pid is None or pid not in PRODUCTS:
            return self._send(404, {"error": "not_found", "message": "product not found"})
        if path.endswith("/final-price"):
            return self._send(200, self._price(pid))
        return self._send(404, {"error": "not_found", "message": "unknown"})

HTTPServer(("127.0.0.1", port), H).serve_forever()
PYCATALOG
    MOCK_PIDS+=($!)

    # ---- MS-09 order mock ----
    python3 - "$ORDER_URL" <<'PYORDER' &
import sys, json
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse

port = int(sys.argv[1].rsplit(":", 1)[-1])

class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _send(self, code, body):
        payload = json.dumps(body).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def do_POST(self):
        path = urlparse(self.path).path
        length = int(self.headers.get("Content-Length", 0) or 0)
        raw = self.rfile.read(length) if length else b"{}"
        try:
            req = json.loads(raw or b"{}")
        except Exception:
            req = {}
        if not path.endswith("/calculate-total"):
            return self._send(404, {"error": "not_found", "message": "unknown"})
        sub = 0.0
        for it in req.get("items", []) or []:
            sub += float(it.get("unit_price", 0) or 0) * int(it.get("quantity", 0) or 0)
        tax = round(sub * 0.15, 2)
        total = round(sub + tax, 2)
        return self._send(200, {
            "sub_total": round(sub, 2), "tax_total": tax, "total": total,
            "totals": [
                {"code": "order.total.subtotal", "value": round(sub, 2), "sort_order": 5},
                {"code": "order.total.tax", "value": tax, "sort_order": 100},
                {"code": "order.total.total", "value": total, "sort_order": 300},
            ],
        })

HTTPServer(("127.0.0.1", port), H).serve_forever()
PYORDER
    MOCK_PIDS+=($!)

